CREATE DEFINER=`adrian.rios`@`%` FUNCTION `fn_get_phone_by_country`(
    p_country_code VARCHAR(5)
) RETURNS varchar(20) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
    CASE p_country_code
        WHEN 'US' THEN RETURN CONCAT('+1', FLOOR(2000000000 + RAND() * 7999999999));
        WHEN 'MX' THEN RETURN CONCAT('+52', FLOOR(1000000000 + RAND() * 8999999999));
        WHEN 'CO' THEN RETURN CONCAT('+57', FLOOR(3000000000 + RAND() * 6999999999));
        WHEN 'PE' THEN RETURN CONCAT('+51', FLOOR(900000000 + RAND() * 899999999));
        WHEN 'AR' THEN RETURN CONCAT('+54', FLOOR(1100000000 + RAND() * 8999999999));
        ELSE RETURN CONCAT('+', FLOOR(10 + RAND() * 89), FLOOR(1000000000 + RAND() * 8999999999));
    END CASE;
END ;;
DELIMITER ;
