DELIMITER ;;
CREATE DEFINER=`adrian.rios`@`%` FUNCTION `fn_get_random_birth_date`(
    p_min_age INT, 
    p_max_age INT
) RETURNS date
    NO SQL
    DETERMINISTIC
BEGIN
    DECLARE v_min_date DATE;
    DECLARE v_max_date DATE;
    DECLARE v_days_diff INT;

    SET p_min_age = IFNULL(p_min_age, 18);
    SET p_max_age = IFNULL(p_max_age, 65);

    SET v_max_date = DATE_SUB(CURDATE(), INTERVAL p_min_age YEAR);
    SET v_min_date = DATE_SUB(CURDATE(), INTERVAL p_max_age + 1 YEAR);
    SET v_days_diff = DATEDIFF(v_max_date, v_min_date);

    RETURN DATE_ADD(v_min_date, INTERVAL FLOOR(RAND() * (v_days_diff + 1)) DAY);
END ;;
DELIMITER ;
