DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_simulate_birthdate`() RETURNS date
    NO SQL
BEGIN
    DECLARE v_rand DOUBLE;
    DECLARE v_min_age INT;
    DECLARE v_max_age INT;
    DECLARE v_target_age INT;
    DECLARE v_days_offset INT;

    SET v_rand = RAND();

    -- Selección del segmento demográfico
    IF v_rand < 0.20 THEN
        SET v_min_age = 18, v_max_age = 24; -- Jóvenes adultos
    ELSEIF v_rand < 0.55 THEN
        SET v_min_age = 25, v_max_age = 34; -- Adultos jóvenes (Mayor consumo e-commerce)
    ELSEIF v_rand < 0.80 THEN
        SET v_min_age = 35, v_max_age = 44; -- Adultos
    ELSEIF v_rand < 0.92 THEN
        SET v_min_age = 45, v_max_age = 54; -- Adultos maduros
    ELSE
        SET v_min_age = 55, v_max_age = 70; -- Seniors
    END IF;

    SET v_target_age = v_min_age + FLOOR(RAND() * (v_max_age - v_min_age + 1));
    SET v_days_offset = FLOOR(RAND() * 365);

    RETURN DATE_SUB(DATE_SUB(CURDATE(), INTERVAL v_target_age YEAR), INTERVAL v_days_offset DAY);
END ;;
DELIMITER ;
