CREATE DEFINER=`root`@`localhost` FUNCTION `fn_simulate_country_code`() RETURNS char(2) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_country_code CHAR(2);

    SELECT country_code INTO v_country_code
    FROM db_test.tbc_countries
    WHERE status = b'1'
    ORDER BY RAND()
    LIMIT 1;

    RETURN IFNULL(v_country_code, 'MX');
END ;;
