CREATE DEFINER=`root`@`localhost` FUNCTION `fn_simulate_courtesy_title_id`(p_gender_id TINYINT UNSIGNED) RETURNS tinyint unsigned
    READS SQL DATA
BEGIN
    DECLARE v_gender_code VARCHAR(30);
    DECLARE v_title_id TINYINT UNSIGNED;

    SELECT code INTO v_gender_code
    FROM db_test.tbc_gender_options
    WHERE gender_ID = p_gender_id;

    -- Asignación coherente o neutra
    IF v_gender_code = 'FEMALE' THEN
        SELECT courtesy_title_ID INTO v_title_id 
        FROM db_test.tbc_courtesy_titles 
        WHERE code IN ('MRS', 'MISS', 'DRA') AND status = b'1' 
        ORDER BY RAND() LIMIT 1;
    ELSEIF v_gender_code = 'MALE' THEN
        SELECT courtesy_title_ID INTO v_title_id 
        FROM db_test.tbc_courtesy_titles 
        WHERE code IN ('MR', 'DR', 'PROF') AND status = b'1' 
        ORDER BY RAND() LIMIT 1;
    ELSE
        SELECT courtesy_title_ID INTO v_title_id 
        FROM db_test.tbc_courtesy_titles 
        WHERE code IN ('MX', 'PROF', 'DR', 'DRA') AND status = b'1' 
        ORDER BY RAND() LIMIT 1;
    END IF;

    RETURN v_title_id;
END ;;
DELIMITER ;
