CREATE DEFINER=`adrian.rios`@`%` PROCEDURE `sp_bulk_insert_full_users`(
    IN p_total INT
)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_new_user_id INT;
    DECLARE v_email VARCHAR(150);
    DECLARE v_nickname VARCHAR(80);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET FOREIGN_KEY_CHECKS = 1;
        SET UNIQUE_CHECKS = 1;
        SET AUTOCOMMIT = 1;
        RESIGNAL;
    END;

    SET AUTOCOMMIT = 0;
    SET FOREIGN_KEY_CHECKS = 0;
    SET UNIQUE_CHECKS = 0;

    START TRANSACTION;

    WHILE i <= p_total DO
        SET v_email = CONCAT('user_', i, '_', FLOOR(1000 + RAND() * 9000), '@utxicotepec.edu.mx');
        SET v_nickname = CONCAT('ING-USER-', i);

        -- 1. Inserción en tb_users
        INSERT INTO `tb_users` (`email`, `nickname`) VALUES (v_email, v_nickname);
        SET v_new_user_id = LAST_INSERT_ID();

        -- 2. Inserción en tb_persons (ajustar nombre de la tabla si difiere)
        INSERT INTO `tb_persons` (
            `user_ID`, 
            `courtesy_title`, 
            `given_names`, 
            `family_names`, 
            `birth_date`, 
            `gender_ID`, 
            `country_code`, 
            `phone`, 
            `status`, 
            `creation_date`, 
            `last_update`
        ) VALUES (
            v_new_user_id,
            ELT(FLOOR(1 + RAND() * 4), 'Sr.', 'Sra.', 'Ing.', 'Lic.'),
            ELT(FLOOR(1 + RAND() * 5), 'Juan', 'María', 'Sofía', 'Carlos', 'Ana'),
            ELT(FLOOR(1 + RAND() * 5), 'Pérez López', 'Fernández Torres', 'Ramírez Castro', 'García Hernández', 'López Gómez'),
            DATE_ADD('1990-01-01', INTERVAL FLOOR(RAND() * 5000) DAY),
            FLOOR(1 + RAND() * 2),
            ELT(FLOOR(1 + RAND() * 5), 'MX', 'CO', 'PE', 'AR', 'CL'),
            CONCAT('+52', FLOOR(1000000000 + RAND() * 9000000000)),
            1,
            NOW(),
            NOW()
        );

        SET i = i + 1;
    END WHILE;

    COMMIT;

    SET FOREIGN_KEY_CHECKS = 1;
    SET UNIQUE_CHECKS = 1;
    SET AUTOCOMMIT = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
