CREATE DEFINER=`adrian.rios`@`%` PROCEDURE `sp_bulk_insert_persons`(
    IN p_total INT,
    IN p_start_user_id INT -- ID de usuario inicial para vincular
)
BEGIN
    DECLARE i INT DEFAULT 0;
    DECLARE v_user_id INT;
    DECLARE v_title VARCHAR(20);
    DECLARE v_given_names VARCHAR(100);
    DECLARE v_family_names VARCHAR(100);
    DECLARE v_birth_date DATE;
    DECLARE v_gender_id INT;
    DECLARE v_country VARCHAR(5);
    DECLARE v_phone VARCHAR(20);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET FOREIGN_KEY_CHECKS = 1;
        SET UNIQUE_CHECKS = 1;
        SET AUTOCOMMIT = 1;
        RESIGNAL;
    END;

    SET AUTOCOMMIT = 0;
    SET FOREIGN_KEY_CHECKS = 0;
    SET UNIQUE_CHECKS = 0;

    START TRANSACTION;

    WHILE i < p_total DO
        SET v_user_id = p_start_user_id + i;
        
        -- Títulos de cortesía aleatorios
        SET v_title = ELT(FLOOR(1 + RAND() * 6), 'Sr.', 'Sra.', 'Dr.', 'Dra.', 'Ing.', 'Lic.');
        
        -- Nombres y apellidos aleatorios
        SET v_given_names = ELT(FLOOR(1 + RAND() * 8), 
            'Juan', 'María Fernanda', 'Sofía', 'Carlos', 'Ana', 'Luis', 'Valeria', 'Diego');
            
        SET v_family_names = CONCAT(
            ELT(FLOOR(1 + RAND() * 6), 'Pérez', 'Fernández', 'Ramírez', 'García', 'López', 'Torres'),
            ' ',
            ELT(FLOOR(1 + RAND() * 6), 'López', 'Torres', 'Castro', 'Hernández', 'Gómez', 'Rojas')
        );

        -- Fecha de nacimiento aleatoria (entre 1970 y 2005)
        SET v_birth_date = DATE_ADD('1970-01-01', INTERVAL FLOOR(RAND() * 12784) DAY);

        -- Género (1 o 2)
        SET v_gender_id = FLOOR(1 + RAND() * 2);

        -- Código de país (ISO Alpha-2)
        SET v_country = ELT(FLOOR(1 + RAND() * 6), 'MX', 'CO', 'PE', 'AR', 'CL', 'ES');

        -- Número telefónico generado
        SET v_phone = CONCAT('+52', FLOOR(1000000000 + RAND() * 9000000000));

        -- Ajusta 'tb_persons' por el nombre exacto de la tabla en tu base de datos
        INSERT INTO `tb_persons` (
            `user_ID`, 
            `courtesy_title`, 
            `given_names`, 
            `family_names`, 
            `birth_date`, 
            `gender_ID`, 
            `country_code`, 
            `phone`, 
            `status`, 
            `creation_date`, 
            `last_update`
        ) VALUES (
            v_user_id,
            v_title,
            v_given_names,
            v_family_names,
            v_birth_date,
            v_gender_id,
            v_country,
            v_phone,
            1,
            NOW(),
            NOW()
        );

        SET i = i + 1;
    END WHILE;

    COMMIT;

    SET FOREIGN_KEY_CHECKS = 1;
    SET UNIQUE_CHECKS = 1;
    SET AUTOCOMMIT = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
