CREATE DEFINER=`adrian.rios`@`%` PROCEDURE `sp_bulk_insert_users`(
    IN p_total INT
)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_email VARCHAR(150);
    DECLARE v_nickname VARCHAR(80);
    DECLARE v_nationality VARCHAR(50);

    -- Control de excepciones: realiza ROLLBACK en caso de error
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET FOREIGN_KEY_CHECKS = 1;
        SET UNIQUE_CHECKS = 1;
        SET AUTOCOMMIT = 1;
        RESIGNAL;
    END;

    -- Optimizaciones de rendimiento para motor InnoDB
    SET AUTOCOMMIT = 0;
    SET FOREIGN_KEY_CHECKS = 0;
    SET UNIQUE_CHECKS = 0;

    START TRANSACTION;

    WHILE i <= p_total DO
        -- Generación de correo y nickname variados
        SET v_email = CONCAT('user_', i, '_', FLOOR(1000 + RAND() * 9000), '@utxicotepec.edu.mx');
        SET v_nickname = CONCAT('ING-USER-', i);

        -- Selección aleatoria de nacionalidad
        SET v_nationality = ELT(FLOOR(1 + RAND() * 10), 
            'Mexicana', 'Colombiana', 'Argentina', 'Española', 'Mexicana',
            'Chilena', 'Peruana', 'Uruguaya', 'Ecuatoriana', 'Venezolana');

        -- Inserción masiva en tb_users
        INSERT INTO `tb_users` (`email`, `nickname`, `nationality`)
        VALUES (v_email, v_nickname, v_nationality);

        SET i = i + 1;
    END WHILE;

    COMMIT;

    -- Restaurar parámetros de sesión
    SET FOREIGN_KEY_CHECKS = 1;
    SET UNIQUE_CHECKS = 1;
    SET AUTOCOMMIT = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_generate_bulk_users` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
