CREATE DEFINER=`adrian.rios`@`%` PROCEDURE `sp_generate_bulk_users`(
    IN p_total INT,
    IN p_forced_country VARCHAR(5),
    IN p_min_age INT,
    IN p_max_age INT,
    IN p_active_ratio INT
)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_new_user_id INT;
    DECLARE v_email VARCHAR(150);
    DECLARE v_nickname VARCHAR(80);
    DECLARE v_password VARCHAR(255);
    DECLARE v_country CHAR(2);
    DECLARE v_status BIT(1);
    DECLARE v_birth_date DATE;
    DECLARE v_phone VARCHAR(25);
    DECLARE v_batch_ts BIGINT;
    
    DECLARE v_min_years INT;
    DECLARE v_max_years INT;
    DECLARE v_min_date DATE;
    DECLARE v_max_date DATE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET FOREIGN_KEY_CHECKS = 1;
        SET UNIQUE_CHECKS = 1;
        SET AUTOCOMMIT = 1;
        RESIGNAL;
    END;

    SET AUTOCOMMIT = 0;
    SET FOREIGN_KEY_CHECKS = 0;
    SET UNIQUE_CHECKS = 0;

    SET v_min_years = IFNULL(p_min_age, 18);
    SET v_max_years = IFNULL(p_max_age, 65);
    SET v_batch_ts = UNIX_TIMESTAMP();

    START TRANSACTION;

    WHILE i <= p_total DO
        -- Generación de correo y nickname totalmente únicos por lote
        SET v_email = CONCAT('bulk_', v_batch_ts, '_', i, '_', FLOOR(RAND() * 10000), '@utxicotepec.edu.mx');
        SET v_nickname = CONCAT('USER-', v_batch_ts, '-', i);
        SET v_password = SHA2(CONCAT('Password123!', i, RAND()), 256);

        IF p_forced_country IS NOT NULL AND p_forced_country <> '' THEN
            SET v_country = LEFT(p_forced_country, 2);
        ELSE
            SET v_country = ELT(FLOOR(1 + RAND() * 6), 'MX', 'US', 'CO', 'PE', 'AR', 'CL');
        END IF;

        IF p_active_ratio IS NOT NULL THEN
            SET v_status = IF((RAND() * 100) < p_active_ratio, b'1', b'0');
        ELSE
            SET v_status = b'1';
        END IF;

        SET v_max_date = DATE_SUB(CURDATE(), INTERVAL v_min_years YEAR);
        SET v_min_date = DATE_SUB(CURDATE(), INTERVAL v_max_years + 1 YEAR);
        SET v_birth_date = DATE_ADD(v_min_date, INTERVAL FLOOR(RAND() * (DATEDIFF(v_max_date, v_min_date) + 1)) DAY);

        CASE v_country
            WHEN 'US' THEN SET v_phone = CONCAT('+1', FLOOR(2000000000 + RAND() * 7999999999));
            WHEN 'MX' THEN SET v_phone = CONCAT('+52', FLOOR(1000000000 + RAND() * 8999999999));
            WHEN 'CO' THEN SET v_phone = CONCAT('+57', FLOOR(3000000000 + RAND() * 6999999999));
            WHEN 'PE' THEN SET v_phone = CONCAT('+51', FLOOR(900000000 + RAND() * 899999999));
            WHEN 'AR' THEN SET v_phone = CONCAT('+54', FLOOR(1100000000 + RAND() * 8999999999));
            ELSE SET v_phone = CONCAT('+', FLOOR(10 + RAND() * 89), FLOOR(1000000000 + RAND() * 8999999999));
        END CASE;

        INSERT INTO `tb_users` (`email`, `nickname`, `password`)
        VALUES (v_email, v_nickname, v_password);

        SET v_new_user_id = LAST_INSERT_ID();

        INSERT INTO `tb_people` (
            `user_ID`,
            `courtesy_title`,
            `given_names`,
            `family_names`,
            `birth_date`,
            `gender_ID`,
            `country_code`,
            `phone`,
            `status`,
            `creation_date`,
            `last_update`
        ) VALUES (
            v_new_user_id,
            ELT(FLOOR(1 + RAND() * 4), 'Sr.', 'Sra.', 'Ing.', 'Lic.'),
            ELT(FLOOR(1 + RAND() * 6), 'John', 'Emily', 'Carlos', 'Ana', 'Michael', 'Sofia'),
            ELT(FLOOR(1 + RAND() * 6), 'Smith', 'Johnson', 'Pérez', 'García', 'Williams', 'López'),
            v_birth_date,
            FLOOR(1 + RAND() * 2),
            v_country,
            v_phone,
            v_status,
            NOW(),
            NOW()
        );

        SET i = i + 1;
    END WHILE;

    COMMIT;

    SET FOREIGN_KEY_CHECKS = 1;
    SET UNIQUE_CHECKS = 1;
    SET AUTOCOMMIT = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_register_user_with_person` */;
