DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_simulate_single_user`(
    OUT p_created_user_id INT UNSIGNED
)
BEGIN
    DECLARE v_user_id INT UNSIGNED;
    DECLARE v_unique_hash VARCHAR(12);
    DECLARE v_email VARCHAR(150);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_given_name VARCHAR(100);
    DECLARE v_family_name VARCHAR(100);
    DECLARE v_birth_date DATE;
    DECLARE v_gender_id TINYINT UNSIGNED;
    DECLARE v_country_code CHAR(2);
    DECLARE v_title_id TINYINT UNSIGNED;
    DECLARE v_phone VARCHAR(25);

    -- Generador de sufijo único para nick y email
    SET v_unique_hash = SUBSTRING(MD5(RAND()), 1, 8);
    SET v_nick = CONCAT('user_', v_unique_hash);
    SET v_email = CONCAT('sim_', v_unique_hash, '@example.com');

    -- Muestras aleatorias de nombres y apellidos sintéticos
    SET v_given_name = ELT(1 + FLOOR(RAND() * 10), 
        'Carlos', 'María', 'Alejandro', 'Sofia', 'Mateo', 'Valentina', 'Javier', 'Camila', 'Diego', 'Lucía');
    SET v_family_name = ELT(1 + FLOOR(RAND() * 10), 
        'Hernández', 'García', 'Martínez', 'López', 'González', 'Pérez', 'Rodríguez', 'Sánchez', 'Ramírez', 'Flores');

    -- Invocación de funciones modulares
    SET v_birth_date = fn_simulate_birthdate();
    SET v_gender_id = fn_simulate_gender_id();
    SET v_country_code = fn_simulate_country_code();
    SET v_title_id = fn_simulate_courtesy_title_id(v_gender_id);
    SET v_phone = CONCAT('+52', FLOOR(5500000000 + (RAND() * 4499999999)));

    -- 1. Insertar en tb_users
    INSERT INTO db_test.tb_users (
        email, 
        nick, 
        password, 
        status
    ) VALUES (
        v_email, 
        v_nick, 
        '$2y$10$abcdefghijklmnopqrstuuuDummyHashForSimulatedUsers', 
        b'1'
    );

    SET v_user_id = LAST_INSERT_ID();

    -- 2. Insertar en tb_people (Relación 1:1)
    INSERT INTO db_test.tb_people (
        user_ID,
        courtesy_title_ID,
        given_names,
        family_names,
        birth_date,
        gender_ID,
        country_code,
        phone,
        status
    ) VALUES (
        v_user_id,
        v_title_id,
        v_given_name,
        v_family_name,
        v_birth_date,
        v_gender_id,
        v_country_code,
        v_phone,
        b'1'
    );

    SET p_created_user_id = v_user_id;
END ;;
DELIMITER ;
