CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_simulate_users_bulk`(
    IN p_quantity INT UNSIGNED,
    IN p_batch_size INT UNSIGNED
)
BEGIN
    DECLARE v_counter INT UNSIGNED DEFAULT 0;
    DECLARE v_batch_counter INT UNSIGNED DEFAULT 0;
    DECLARE v_dummy_id INT UNSIGNED;
    DECLARE v_effective_batch INT UNSIGNED;

    -- Ajuste por defecto de tamaño de bloque
    SET v_effective_batch = IF(p_batch_size IS NULL OR p_batch_size = 0, 500, p_batch_size);

    START TRANSACTION;

    WHILE v_counter < p_quantity DO
        CALL sp_simulate_single_user(v_dummy_id);
        
        SET v_counter = v_counter + 1;
        SET v_batch_counter = v_batch_counter + 1;

        -- Commit parcial para liberar memoria e índices
        IF v_batch_counter >= v_effective_batch THEN
            COMMIT;
            START TRANSACTION;
            SET v_batch_counter = 0;
        END IF;
    END WHILE;

    COMMIT;

    SELECT CONCAT('Simulación completada con éxito. Total de usuarios creados: ', v_counter) AS result;
END ;;
DELIMITER ;
